#!/usr/bin/env swift

// create_reminder.swift
// Creates an Apple Reminder at a specific timestamp and location using EventKit.
// Usage: swift create_reminder.swift
// Requires macOS and Reminders permission grant on first run.

import Foundation
import EventKit
import CoreLocation

// ─── Configuration ───────────────────────────────────────────────────────────

let reminderTitle    = "Reminder (6h after Lunch with Jordan)"
let reminderNotes    = "Auto-generated: 6-hour gap between 'Lunch with Jordan' (12:30 PM) and 'Follow up with Maya' (6:30 PM), added to base timestamp 1788269400.0."
let unixTimestamp    = 1788291000.0                    // Sep 1, 2026 19:30:00 UTC
let latitude         = 37.7749                         // San Francisco
let longitude        = -122.4194
let locationRadius   = 100.0                           // meters
let locationTitle    = "San Francisco, CA"
let targetListName   : String? = nil                   // nil = default list

// ─── Main ────────────────────────────────────────────────────────────────────

let eventStore = EKEventStore()
let semaphore  = DispatchSemaphore(value: 0)

func requestAccess(completion: @escaping (Bool) -> Void) {
    if #available(macOS 14.0, *) {
        eventStore.requestFullAccessToReminders { granted, error in
            if let error = error {
                print("❌ Access error: \(error.localizedDescription)")
            }
            completion(granted)
        }
    } else {
        eventStore.requestAccess(to: .reminder) { granted, error in
            if let error = error {
                print("❌ Access error: \(error.localizedDescription)")
            }
            completion(granted)
        }
    }
}

print("🔐 Requesting Reminders access…")

requestAccess { granted in
    defer { semaphore.signal() }

    guard granted else {
        print("❌ Reminders access denied. Grant permission in System Settings → Privacy & Security → Reminders.")
        return
    }
    print("✅ Access granted.")

    // ── Resolve target calendar (list) ───────────────────────────────────
    let calendar: EKCalendar
    if let name = targetListName,
       let match = eventStore.calendars(for: .reminder).first(where: { $0.title == name }) {
        calendar = match
        print("📋 Using list: \(name)")
    } else if let defaultCal = eventStore.defaultCalendarForNewReminders() {
        calendar = defaultCal
        print("📋 Using default list: \(defaultCal.title)")
    } else {
        print("❌ No reminder list available.")
        return
    }

    // ── Create the reminder ──────────────────────────────────────────────
    let reminder       = EKReminder(eventStore: eventStore)
    reminder.title     = reminderTitle
    reminder.notes     = reminderNotes
    reminder.calendar  = calendar

    // Due date from Unix timestamp
    let dueDate        = Date(timeIntervalSince1970: unixTimestamp)
    let dueDateComps   = Calendar.current.dateComponents(
        [.year, .month, .day, .hour, .minute, .second, .timeZone],
        from: dueDate
    )
    reminder.dueDateComponents = dueDateComps

    // Alarm at the exact due time
    let alarm = EKAlarm(absoluteDate: dueDate)
    reminder.addAlarm(alarm)

    // ── Location ─────────────────────────────────────────────────────────
    let structuredLoc       = EKStructuredLocation(title: locationTitle)
    structuredLoc.geoLocation = CLLocation(latitude: latitude, longitude: longitude)
    structuredLoc.radius      = locationRadius

    let locationAlarm              = EKAlarm()
    locationAlarm.structuredLocation = structuredLoc
    locationAlarm.proximity          = .enter          // trigger on arrival
    reminder.addAlarm(locationAlarm)

    // ── Save ─────────────────────────────────────────────────────────────
    do {
        try eventStore.save(reminder, commit: true)
        let formatter        = DateFormatter()
        formatter.dateStyle  = .full
        formatter.timeStyle  = .long
        formatter.timeZone   = TimeZone.current

        print("")
        print("══════════════════════════════════════════════")
        print("  ✅  Reminder Created Successfully")
        print("══════════════════════════════════════════════")
        print("  Title:     \(reminderTitle)")
        print("  Due:       \(formatter.string(from: dueDate))")
        print("  Timestamp: \(unixTimestamp)")
        print("  Location:  \(locationTitle) (\(latitude), \(longitude))")
        print("  Radius:    \(Int(locationRadius))m (trigger on arrival)")
        print("  List:      \(calendar.title)")
        print("══════════════════════════════════════════════")
    } catch {
        print("❌ Failed to save reminder: \(error.localizedDescription)")
    }
}

semaphore.wait()

